import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

matmul_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

#define TILE_M 64
#define TILE_N 64
#define TILE_K 8
#define THREADS_X 16
#define THREADS_Y 16
__global__ void matmul_kernel(const float* __restrict__ A,
                               const float* __restrict__ B,
                               float* __restrict__ C,
                               int M, int N, int K, int kChunk) {
    __shared__ float As[2][TILE_M][TILE_K];
    __shared__ float Bs[2][TILE_K][TILE_N];
    int tx = threadIdx.x; // 0..15
    int ty = threadIdx.y; // 0..15
    int blockRow = blockIdx.y * TILE_M;
    int blockCol = blockIdx.x * TILE_N;
    int kStart = blockIdx.z * kChunk;
    int kEnd = kStart + kChunk;
    if (kEnd > K) kEnd = K;
    int tid = ty * THREADS_X + tx;
    float sum[4][4];
    #pragma unroll
    for (int i = 0; i < 4; i++)
        #pragma unroll
        for (int j = 0; j < 4; j++)
            sum[i][j] = 0.0f;
    // Load one K-tile of A and B into the given shared-memory buffer.
    // Uses vectorized (float4) global loads for coalesced access.
    #define LOAD_TILE(k0, buf) do { \
        _Pragma("unroll") \
        for (int idx4 = tid; idx4 < (TILE_M * TILE_K) / 4; idx4 += THREADS_X * THREADS_Y) { \
            int m = idx4 / (TILE_K / 4); \
            int kk4 = idx4 % (TILE_K / 4); \
            int globalRow = blockRow + m; \
            int globalK = (k0) + kk4 * 4; \
            float4 val; \
            if (globalRow < M && globalK + 3 < kEnd) { \
                val = *reinterpret_cast<const float4*>(&A[globalRow * K + globalK]); \
            } else { \
                val.x = (globalRow < M && globalK + 0 < kEnd) ? A[globalRow * K + globalK + 0] : 0.0f; \
                val.y = (globalRow < M && globalK + 1 < kEnd) ? A[globalRow * K + globalK + 1] : 0.0f; \
                val.z = (globalRow < M && globalK + 2 < kEnd) ? A[globalRow * K + globalK + 2] : 0.0f; \
                val.w = (globalRow < M && globalK + 3 < kEnd) ? A[globalRow * K + globalK + 3] : 0.0f; \
            } \
            As[buf][m][kk4 * 4 + 0] = val.x; \
            As[buf][m][kk4 * 4 + 1] = val.y; \
            As[buf][m][kk4 * 4 + 2] = val.z; \
            As[buf][m][kk4 * 4 + 3] = val.w; \
        } \
        _Pragma("unroll") \
        for (int idx4 = tid; idx4 < (TILE_K * TILE_N) / 4; idx4 += THREADS_X * THREADS_Y) { \
            int kk = idx4 / (TILE_N / 4); \
            int n4 = idx4 % (TILE_N / 4); \
            int globalK = (k0) + kk; \
            int globalCol = blockCol + n4 * 4; \
            float4 val; \
            if (globalK < kEnd && globalCol + 3 < N) { \
                val = *reinterpret_cast<const float4*>(&B[globalK * N + globalCol]); \
            } else { \
                val.x = (globalK < kEnd && globalCol + 0 < N) ? B[globalK * N + globalCol + 0] : 0.0f; \
                val.y = (globalK < kEnd && globalCol + 1 < N) ? B[globalK * N + globalCol + 1] : 0.0f; \
                val.z = (globalK < kEnd && globalCol + 2 < N) ? B[globalK * N + globalCol + 2] : 0.0f; \
                val.w = (globalK < kEnd && globalCol + 3 < N) ? B[globalK * N + globalCol + 3] : 0.0f; \
            } \
            Bs[buf][kk][n4 * 4 + 0] = val.x; \
            Bs[buf][kk][n4 * 4 + 1] = val.y; \
            Bs[buf][kk][n4 * 4 + 2] = val.z; \
            Bs[buf][kk][n4 * 4 + 3] = val.w; \
        } \
    } while (0)
    int curBuf = 0;
    LOAD_TILE(kStart, curBuf);
    __syncthreads();
    for (int k0 = kStart; k0 < kEnd; k0 += TILE_K) {
        int nextK0 = k0 + TILE_K;
        int nextBuf = 1 - curBuf;
        // Prefetch the next K-tile into the other shared-memory buffer
        // while we still compute with the current buffer below, allowing
        // the compiler/scheduler to overlap global memory latency with FMA work.
        if (nextK0 < kEnd) {
            LOAD_TILE(nextK0, nextBuf);
        }
        #pragma unroll
        for (int kk = 0; kk < TILE_K; kk++) {
            float a[4], b[4];
            #pragma unroll
            for (int i = 0; i < 4; i++) a[i] = As[curBuf][ty + i * THREADS_Y][kk];
            #pragma unroll
            for (int j = 0; j < 4; j++) b[j] = Bs[curBuf][kk][tx + j * THREADS_X];
            #pragma unroll
            for (int i = 0; i < 4; i++) {
                #pragma unroll
                for (int j = 0; j < 4; j++) {
                    sum[i][j] += a[i] * b[j];
                }
            }
        }
        __syncthreads();
        curBuf = nextBuf;
    }
    #undef LOAD_TILE
    float* Cout = C + (size_t)blockIdx.z * (size_t)M * (size_t)N;
    #pragma unroll
    for (int i = 0; i < 4; i++) {
        int row = blockRow + ty + i * THREADS_Y;
        if (row >= M) continue;
        #pragma unroll
        for (int j = 0; j < 4; j++) {
            int col = blockCol + tx + j * THREADS_X;
            if (col < N) Cout[row * N + col] = sum[i][j];
        }
    }
}
// Split-K reduction kernel: sums the per-K-block partial results
// (stored contiguously as [numKBlocks, M, N]) into the final output,
// avoiding the global-memory atomicAdd contention that a naive
// split-K accumulation would otherwise incur.
__global__ void reduce_partial_kernel(const float* __restrict__ partial,
                                       float* __restrict__ out,
                                       int M, int N, int numKBlocks) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = M * N;
    if (idx >= total) return;
    float sum = 0.0f;
    for (int k = 0; k < numKBlocks; k++) {
        sum += partial[(size_t)k * (size_t)total + idx];
    }
    out[idx] = sum;
}
torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.is_cuda(), "A must be a CUDA tensor");
    TORCH_CHECK(B.is_cuda(), "B must be a CUDA tensor");
    TORCH_CHECK(A.dtype() == torch::kFloat32, "A must be float32");
    TORCH_CHECK(B.dtype() == torch::kFloat32, "B must be float32");
    A = A.contiguous();
    B = B.contiguous();
    int M = A.size(0);
    int K = A.size(1);
    int N = B.size(1);
    const int kChunk = 16384;
    int numKBlocks = (K + kChunk - 1) / kChunk;
    auto Cpartial = torch::empty({numKBlocks, M, N}, A.options());
    auto C = torch::empty({M, N}, A.options());
    dim3 block(THREADS_X, THREADS_Y);
    dim3 grid((N + TILE_N - 1) / TILE_N, (M + TILE_M - 1) / TILE_M, numKBlocks);
    matmul_kernel<<<grid, block>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        Cpartial.data_ptr<float>(),
        M, N, K, kChunk
    );
    int total = M * N;
    int threads = 256;
    int blocks = (total + threads - 1) / threads;
    reduce_partial_kernel<<<blocks, threads>>>(
        Cpartial.data_ptr<float>(),
        C.data_ptr<float>(),
        M, N, numKBlocks
    );
    return C;
}
"""

matmul_cpp_source = "torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B);"

matmul_module = load_inline(
    name="matmul_module",
    cpp_sources=matmul_cpp_source,
    cuda_sources=matmul_source,
    functions=["matmul_cuda"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Optimized model that performs a single matrix multiplication (C = A * B)
    with a large K dimension using a custom CUDA kernel that splits the K
    dimension across the grid's z-dimension and accumulates partial sums
    via atomicAdd.
    """
    def __init__(self):
        super(ModelNew, self).__init__()

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return matmul_module.matmul_cuda(A.cuda(), B.cuda())


M = 256
N = 256
K = 131072 * 4


def get_inputs():
    A = torch.rand(M, K)
    B = torch.rand(K, N)
    return [A, B]


